    private static VoxelShape[] bake(double[][] boxes) {
        VoxelShape[] result = new VoxelShape[4];
        for (int turn=0; turn<4; turn++) {
            VoxelShape shape = Shapes.empty();
            for (double[] source : boxes) {
                double x1=source[0], z1=source[2], x2=source[3], z2=source[5];
                for (int i=0; i<turn; i++) { double nx1=16-z2, nx2=16-z1; z1=x1; z2=x2; x1=nx1; x2=nx2; }
                shape = Shapes.or(shape, Block.box(x1,source[1],z1,x2,source[4],z2));
            }
            result[turn] = shape.optimize();
        }
        return result;
    }
    public static VoxelShape get(String name, Direction facing) {
        VoxelShape[] shapes = SHAPES.get(name);
        int turn = switch (facing) { case EAST -> 1; case SOUTH -> 2; case WEST -> 3; default -> 0; };
        return shapes == null ? Shapes.block() : shapes[turn];
    }
    private FactoryShapes() {}
